// trainer.cpp — 32-bit value scanner + freezer
// Platform: Windows (x86/x64), C++17
//
// Build (MSVC):    cl /std:c++17 /EHsc /O2 trainer.cpp
// Build (MinGW):   x86_64-w64-mingw32-g++ -std=c++17 -O2 -static trainer.cpp -o trainer.exe
// Run:             trainer.exe <process.exe | pid>
//
// Flow: initial scan -> narrow pass 1 -> narrow pass 2 -> pick address -> freeze @ 50ms

#define NOMINMAX
#include <windows.h>
#include <tlhelp32.h>

#include <atomic>
#include <chrono>
#include <cstdint>
#include <cstdlib>
#include <iostream>
#include <limits>
#include <string>
#include <thread>
#include <vector>

namespace {

DWORD findPidByName(const std::string& name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    if (snap == INVALID_HANDLE_VALUE) return 0;

    PROCESSENTRY32 entry{};
    entry.dwSize = sizeof(entry);
    DWORD pid = 0;

    if (Process32First(snap, &entry)) {
        do {
            if (_stricmp(entry.szExeFile, name.c_str()) == 0) {
                pid = entry.th32ProcessID;
                break;
            }
        } while (Process32Next(snap, &entry));
    }
    CloseHandle(snap);
    return pid;
}

DWORD resolvePid(const std::string& arg) {
    char* end = nullptr;
    unsigned long n = std::strtoul(arg.c_str(), &end, 10);
    if (end && *end == '\0' && n != 0) return static_cast<DWORD>(n);
    return findPidByName(arg);
}

bool isWritable(DWORD protect) {
    if (protect & (PAGE_GUARD | PAGE_NOACCESS)) return false;
    constexpr DWORD writable =
        PAGE_READWRITE | PAGE_WRITECOPY | PAGE_EXECUTE_READWRITE | PAGE_EXECUTE_WRITECOPY;
    return (protect & writable) != 0;
}

// Walks every committed, writable region and collects 4-byte-aligned matches.
std::vector<uintptr_t> firstScan(HANDLE proc, int32_t target) {
    std::vector<uintptr_t> hits;
    SYSTEM_INFO si{};
    GetSystemInfo(&si);

    auto addr = reinterpret_cast<uintptr_t>(si.lpMinimumApplicationAddress);
    const auto maxAddr = reinterpret_cast<uintptr_t>(si.lpMaximumApplicationAddress);

    constexpr size_t kChunk = 1 << 20;  // read regions in 1 MiB slices
    std::vector<uint8_t> buf(kChunk);

    MEMORY_BASIC_INFORMATION mbi{};
    while (addr < maxAddr &&
           VirtualQueryEx(proc, reinterpret_cast<LPCVOID>(addr), &mbi, sizeof(mbi)) == sizeof(mbi)) {
        const auto base = reinterpret_cast<uintptr_t>(mbi.BaseAddress);
        const size_t size = mbi.RegionSize;

        if (mbi.State == MEM_COMMIT && isWritable(mbi.Protect)) {
            for (size_t off = 0; off < size; off += kChunk) {
                const size_t want = std::min(kChunk, size - off);
                SIZE_T got = 0;
                if (!ReadProcessMemory(proc, reinterpret_cast<LPCVOID>(base + off),
                                       buf.data(), want, &got) || got < sizeof(int32_t)) {
                    continue;
                }
                for (size_t i = 0; i + sizeof(int32_t) <= got; i += sizeof(int32_t)) {
                    int32_t v;
                    std::memcpy(&v, buf.data() + i, sizeof(v));
                    if (v == target) hits.push_back(base + off + i);
                }
            }
        }

        const uintptr_t next = base + size;
        if (next <= addr) break;  // overflow guard
        addr = next;
    }
    return hits;
}

// Re-reads each surviving address; keeps only those now holding `target`.
std::vector<uintptr_t> narrow(HANDLE proc, const std::vector<uintptr_t>& prev, int32_t target) {
    std::vector<uintptr_t> kept;
    kept.reserve(prev.size());
    for (uintptr_t a : prev) {
        int32_t v = 0;
        SIZE_T got = 0;
        if (ReadProcessMemory(proc, reinterpret_cast<LPCVOID>(a), &v, sizeof(v), &got) &&
            got == sizeof(v) && v == target) {
            kept.push_back(a);
        }
    }
    return kept;
}

template <typename T>
T prompt(const std::string& msg) {
    for (;;) {
        std::cout << msg << std::flush;
        T v{};
        if (std::cin >> v) {
            std::cin.ignore(std::numeric_limits<std::streamsize>::max(), '\n');
            return v;
        }
        if (std::cin.eof()) std::exit(1);
        std::cin.clear();
        std::cin.ignore(std::numeric_limits<std::streamsize>::max(), '\n');
        std::cout << "  invalid input\n";
    }
}

void printHits(HANDLE proc, const std::vector<uintptr_t>& hits, size_t limit = 20) {
    for (size_t i = 0; i < hits.size() && i < limit; ++i) {
        int32_t v = 0;
        ReadProcessMemory(proc, reinterpret_cast<LPCVOID>(hits[i]), &v, sizeof(v), nullptr);
        std::printf("  [%zu] 0x%p = %d\n", i, reinterpret_cast<void*>(hits[i]), v);
    }
    if (hits.size() > limit) std::printf("  ... %zu more\n", hits.size() - limit);
}

}  // namespace

int main(int argc, char** argv) {
    if (argc < 2) {
        std::cerr << "usage: " << argv[0] << " <process.exe | pid>\n";
        return 1;
    }

    const DWORD pid = resolvePid(argv[1]);
    if (!pid) {
        std::cerr << "process not found: " << argv[1] << '\n';
        return 1;
    }

    HANDLE proc = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_VM_OPERATION |
                                  PROCESS_QUERY_INFORMATION,
                              FALSE, pid);
    if (!proc) {
        std::cerr << "OpenProcess failed (" << GetLastError()
                  << "). Try running as administrator.\n";
        return 1;
    }
    std::cout << "attached to pid " << pid << "\n\n";

    // Initial scan.
    const auto v0 = prompt<int32_t>("current value: ");
    auto hits = firstScan(proc, v0);
    std::cout << "  " << hits.size() << " hits\n\n";

    // Two narrowing passes: change the value in-game, then enter the new one.
    for (int pass = 1; pass <= 2 && hits.size() > 1; ++pass) {
        const auto v = prompt<int32_t>("pass " + std::to_string(pass) +
                                       " — change it in-game, new value: ");
        hits = narrow(proc, hits, v);
        std::cout << "  " << hits.size() << " hits\n\n";
    }

    if (hits.empty()) {
        std::cout << "nothing left. value may be stored as float/double, or obfuscated.\n";
        CloseHandle(proc);
        return 0;
    }

    printHits(proc, hits);

    size_t idx = 0;
    if (hits.size() > 1) {
        do {
            idx = prompt<size_t>("index to freeze: ");
        } while (idx >= hits.size());
    }
    const uintptr_t addr = hits[idx];
    const auto frozen = prompt<int32_t>("freeze at value: ");

    std::atomic<bool> running{true};
    std::thread freezer([&] {
        while (running.load(std::memory_order_relaxed)) {
            SIZE_T wrote = 0;
            if (!WriteProcessMemory(proc, reinterpret_cast<LPVOID>(addr), &frozen,
                                    sizeof(frozen), &wrote)) {
                std::cerr << "\nwrite failed (" << GetLastError() << "), stopping\n";
                running = false;
                break;
            }
            std::this_thread::sleep_for(std::chrono::milliseconds(50));
        }
    });

    std::printf("freezing 0x%p = %d every 50ms. press Enter to stop.\n",
                reinterpret_cast<void*>(addr), frozen);
    std::string line;
    std::getline(std::cin, line);

    running = false;
    freezer.join();
    CloseHandle(proc);
    std::cout << "released.\n";
    return 0;
}
